#ifndef SENSOR_H
#define SENSOR_H

#include <string>

class Sensor {
private:
    int id;
    std::string name;
    float value;
public:
    Sensor(int i, std::string n, float v);
    void setValue(float v);
    void printInfo() const;
};

#endif

#include <iostream>
#include "sensor.h"

Sensor::Sensor(int i, std::string n, float v)
    : id(i), name(n), value(v) {}

void Sensor::setValue(float v) {
    value = v;
}

void Sensor::printInfo() const {
    std::cout << "Sensor " << id << " (" << name << "): " << value << "\n";
}

#include "sensor.h"

int main() {
    Sensor s1(1, "TempSensor", 22.5f);
    s1.printInfo();
    s1.setValue(23.1f);
    s1.printInfo();
}

